    border-radius: 4px;
    transition: background-color 0.15s, color 0.15s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.thread-root {
    padding: 12px 16px;
    background-color: rgba(255, 255, 255, 0.03);
    border-bottom: 1px solid #3a3c42;
}

.root-author {
    font-weight: 700;
    color: #e0e0e0;
    font-size: 0.9rem;
    margin-bottom: 4px;
}

.root-content {
    color: #dcddde;
    font-size: 0.9rem;
