arguments.file_text:
.chat-layout {
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    background-color: #313338;
}

@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_4bfcfc251c2c4cb1aae8ffaf0eb88c40.Models
@using sv_4bfcfc251c2c4cb1aae8ffaf0eb88c40.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <!-- Left sidebar -->
    <div class="sidebar-panel">
        <ChannelList Channels="channels"
                     ActiveChannelId="activeChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <!-- Main message area -->
    <div class="message-panel @(threadOpen ? "" : "expanded")">
        @if (activeChannel is not null)
        {
            <div class="channel-header-bar">
                <div>
                    <h2># @activeChannel.Name</h2>
                    <p>@activeChannel.Description</p>
                </div>
            </div>

            <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
                @if (isLoadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var msg in messages)
                {
                    <MessageItem Message="msg"
                                 ReplyCount="GetReplyCount(msg.Id)"
                                 OnOpenThread="OpenThread"
                                 OnReact="HandleReaction" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{activeChannel.Name}")"
                          OnSend="SendMessage" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    <!-- Thread panel -->
    @if (threadOpen)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="threadRootMessage"
                         ThreadMessages="threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadMessages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();

    private Channel? activeChannel;
    private int activeChannelId;
    private Message? threadRootMessage;
    private bool threadOpen;
    private bool isLoadingMore;
    private bool allMessagesLoaded;

    private ElementReference messageListRef;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadSummaries.Clear();
        allMessagesLoaded = false;

        if (activeChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
            await BuildThreadSummaries();
            await ChatService.MarkChannelReadAsync(channelId);

            // Update unread count locally
            var idx = channels.FindIndex(c => c.Id == channelId);
            if (idx >= 0)
            {
                channels[idx] = activeChannel with { UnreadCount = 0 };
                activeChannel = channels[idx];
            }
        }

        // Close thread when switching channels
        CloseThread();
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top pagination is handled via JS interop in production;
        // here we provide the mechanism and the UI trigger.
    }

    internal async Task LoadOlderMessages()
    {
        if (isLoadingMore || allMessagesLoaded || activeChannel is null) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
        if (older.Count < PageSize)
        {
            allMessagesLoaded = true;
        }

        messages.InsertRange(0, older);
        await BuildThreadSummaries();
        isLoadingMore = false;
    }

    private async Task BuildThreadSummaries()
    {
        // Build thread summaries from messages that have replies
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        var replyCounts = messages
            .Where(m => m.ReplyToId is not null && rootIds.Contains(m.ReplyToId.Value))
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in replyCounts)
        {
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }

        await Task.CompletedTask;
    }

    private int GetReplyCount(int messageId)
    {
        return threadSummaries.TryGetValue(messageId, out var summary)
            ? summary.ReplyCount
            : 0;
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendMessage(string content)
    {
        if (activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(msg);
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || activeChannel is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        // Update thread summary count
        if (threadSummaries.TryGetValue(threadRootMessage.Id, out var existing))
        {
            threadSummaries[threadRootMessage.Id] = existing with
            {
