toolArgs.file_text:
.chat-container {
    display: flex;
    height: 100%;
    width: 100%;
}

.sidebar-panel {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
    border-right: 1px solid #3a3c42;
}

.message-panel {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background-color: #313338;
}

.message-panel.expanded {
    /* Takes remaining space when thread is closed */
}

.thread-panel-container {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

.channel-header-bar {
    padding: 12px 16px;
    border-bottom: 1px solid #3a3c42;
    flex-shrink: 0;
}

.channel-header-bar h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #e0e0e0;
}

.channel-header-bar p {
    margin: 2px 0 0;
    font-size: 0.8rem;
    color: #72767d;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #72767d;
    font-size: 0.85rem;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.empty-state p {
    color: #72767d;
    font-size: 1.1rem;
}

